// Math Bridge — Compatibility layer for tri-math migration
// Provides backward compatibility for sacred constants and basic functions
// Advanced functions (PSLQ, continued fractions, zeta) stay in src/sacred/

const std = @import("std");

// ═════════════════════════════════════════════════════════════════════════
// Local imports (fallback when tri-math not available via build.zig)
// ═══════════════════════════════════════════════════════════════════════════════

const local_stdlib = @import("stdlib/math.zig");
const local_stdlib_ext = @import("stdlib/math_ext.zig");

// ═══════════════════════════════════════════════════════════════════════════
// Tri-math integration
// tri-math module is at src/tri/math/ — import as local module
// ═══════════════════════════════════════════════════════════════════════════════════════════════

const has_trimath = true; // tri-math module is available

const trimath = struct {
    pub const SacredConstants = @import("tri/math/sacred_constants.zig");
};

// Base values (from tri-math or local stdlib)
const PHI_BASE: f64 = trimath.SacredConstants.PHI;
const PI_VAL: f64 = trimath.SacredConstants.PI;
const E_VAL: f64 = trimath.SacredConstants.E;
const TAU_VAL: f64 = trimath.SacredConstants.TAU;

// ═════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════
// Sacred Constants exports
// ═════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════